/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type PostMediaType = 'IMAGE' | 'VIDEO'

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type PostMedia = {
  url: string
  type: PostMediaType
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type PostAuthor = {
  id: string
  first_name?: string
  last_name?: string
  avatar_url?: string
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type Post = {
  id: string
  title: string
  content: string
  media: PostMedia[]
  created_at: string
  author: PostAuthor
  is_saved: boolean
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type PostCreatePayload = {
  title: string
  content: string
  media: PostMedia[]
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////
type PostListParams = {
  q?: string
  ids?: string[]
  page?: number
  limit?: number
}
